// Regenerates src/types.generated.ts from a database that has the migrations applied.
//
//   pnpm --filter @mp/db gen-types
//
// Source, in order:
//   1. SUPABASE_PROJECT_REF set (with SUPABASE_ACCESS_TOKEN): the hosted project, over the
//      Management API. This needs no container runtime.
//   2. Otherwise the local stack (`supabase start`), which needs one. CI does this.
//
// The generated file is formatted with Biome so `pnpm lint` stays green. The old file is kept
// if generation fails.
import { spawnSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const target = resolve(dirname(fileURLToPath(import.meta.url)), "../src/types.generated.ts");
const projectRef = process.env.SUPABASE_PROJECT_REF?.trim();

const source = projectRef ? ["--project-id", projectRef] : ["--local"];
const generate = spawnSync(
  "pnpm",
  ["exec", "supabase", "gen", "types", "typescript", "--schema", "public", ...source],
  { encoding: "utf8", maxBuffer: 32 * 1024 * 1024 },
);

// This CLI reports some failures as JSON on stdout, so treat that like a non-zero exit.
const failed =
  generate.status !== 0 ||
  !generate.stdout.trim() ||
  generate.stdout.trimStart().startsWith('{"_tag":"Error"');
if (failed) {
  process.stderr.write(
    `${generate.stderr || generate.stdout || "supabase gen types produced no output"}\n`,
  );
  process.stderr.write(
    projectRef
      ? "Could not read the hosted project. Check SUPABASE_ACCESS_TOKEN.\n"
      : "Could not read the local stack. Run `supabase start` first, or set SUPABASE_PROJECT_REF.\n",
  );
  process.exit(generate.status ?? 1);
}

const header =
  "// Generated by `pnpm --filter @mp/db gen-types` (supabase gen types typescript). Do not edit.\n\n";
writeFileSync(target, header + generate.stdout);

const format = spawnSync("pnpm", ["exec", "biome", "format", "--write", target], {
  encoding: "utf8",
});
if (format.status !== 0) {
  process.stderr.write(format.stderr || format.stdout);
  process.exit(format.status ?? 1);
}
console.log(`Wrote ${target}`);
